import os
import google.cloud.vision_v1 as vision

def extract_receipt_fields(payload, config=None):
    config = config or {}
    client = vision.ImageAnnotatorClient()
    image = vision.Image(content=payload)
    features = [vision.Feature(type_=vision.Feature.Type.DOCUMENT_TEXT_DETECTION)]
    response = client.batch_annotate_images(requests=[vision.AnnotateImageRequest(image=image, features=features)])
    result = {
        'merchant': None,
        'tax': None,
        'total': None,
        'items': []
    }
    for annotation in response.responses[0].full_text_annotation.pages[0].blocks:
        for paragraph in annotation.paragraphs:
            for word in paragraph.words:
                word_text = word.symbols[0].text
                for symbol in word.symbols[1:]:
                    word_text += symbol.text
                if word_text.isdigit() and 'Total' in annotation.description:
                    result['total'] = word_text
                if 'Tax' in annotation.description:
                    result['tax'] = word_text
                if 'Merchant' in annotation.description:
                    result['merchant'] = word_text
                result['items'].append(word_text)
    return result
